(6034833, 886902, 114225, '<td valign="top">Pretty scene. I wonder if you could have gotten rid of the power lines in post (it''s advanced editing), as they really are distracting.</td>', 'Pretty scene. I wonder if you could have gotten rid of the power lines in post (it''s advanced editing), as they really are distracting.', '2010-06-01 09:13:43.000000', NULL, 1),
(6034835, 886700, 114225, '<td valign="top">I like the view point used for this.</td>', 'I like the view point used for this.', '2010-06-01 09:14:13.000000', NULL, 1),
(6034836, 886983, 114225, '<td valign="top">Excellent capture of a man in the middle of this work. I love the choice of color for this.</td>', 'Excellent capture of a man in the middle of this work. I love the choice of color for this.', '2010-06-01 09:14:45.000000', NULL, 1),
(6034838, 886490, 114225, '<td valign="top">Wow, this is playing tricks with my mind. Is it a fish-eye photo, or a curved building? Really cool colors.</td>', 'Wow, this is playing tricks with my mind. Is it a fish-eye photo, or a curved building? Really cool colors.', '2010-06-01 09:15:47.000000', NULL, 1),
(6034839, 886581, 114225, '<td valign="top">Good job capturing this difficult scene. With the bright fire, its definitely hard to get exposure of the background.</td>', 'Good job capturing this difficult scene. With the bright fire, its definitely hard to get exposure of the background.', '2010-06-01 09:16:37.000000', NULL, 1),
(6034886, 887054, 114225, '<td valign="top">Great colors and reflections. Also, a great vantage point not often shown for this city.</td>', 'Great colors and reflections. Also, a great vantage point not often shown for this city.', '2010-06-01 10:01:59.000000', NULL, 1),
(6034887, 886889, 114225, '<td valign="top">Nice job telling a story with this photo!</td>', 'Nice job telling a story with this photo!', '2010-06-01 10:02:38.000000', NULL, 1),
(6034893, 886675, 114225, '<td valign="top">Great balance to this scene. I think I would have liked it slightly more without the ghosts.</td>', 'Great balance to this scene. I think I would have liked it slightly more without the ghosts.', '2010-06-01 10:09:33.000000', NULL, 1),
(6034894, 886734, 114225, '<td valign="top">Great use of light and capturing the moment of mom in the sun and the kids at play.</td>', 'Great use of light and capturing the moment of mom in the sun and the kids at play.', '2010-06-01 10:10:33.000000', NULL, 1),
(6034895, 886677, 114225, '<td valign="top">Excellent use of selective desaturation. Really improves the overall photo.</td>', 'Excellent use of selective desaturation. Really improves the overall photo.', '2010-06-01 10:11:21.000000', NULL, 1),
