INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6036922, 886920, 2553, '<td valign="top">Very nicely done!  This is exactly the kind of image I pictured in my mind that would be perfect for this challenge.  Hope it makes the front page!</td>', 'Very nicely done!  This is exactly the kind of image I pictured in my mind that would be perfect for this challenge.  Hope it makes the front page!', '2010-06-02 04:39:10.000000', NULL, 1),
(6036924, 886902, 2553, '<td valign="top">Very cool.</td>', 'Very cool.', '2010-06-02 04:39:35.000000', NULL, 1),
(6036933, 886881, 2553, '<td valign="top">Like this a lot, the sky really makes the image.</td>', 'Like this a lot, the sky really makes the image.', '2010-06-02 04:40:50.000000', NULL, 1),
(6036935, 886721, 2553, '<td valign="top">Well done, and good timing!</td>', 'Well done, and good timing!', '2010-06-02 04:41:48.000000', NULL, 1),
(6036937, 886931, 47541, '<td valign="top">Nice motorway shot. Something like this won a competition in the Herald a couple of years back. Hopetown Street bridge?<br/> <br/>Nicely exposed, should be your second 6.x night shot with the Sky Tower :)</td>', 'Nice motorway shot. Something like this won a competition in the Herald a couple of years back. Hopetown Street bridge? Nicely exposed, should be your second 6.x night shot with the Sky Tower :)', '2010-06-02 04:42:08.000000', NULL, 1),
(6036944, 886850, 2553, '<td valign="top">A really fascinating image, well captured, and excellent post-processing work.</td>', 'A really fascinating image, well captured, and excellent post-processing work.', '2010-06-02 04:44:28.000000', NULL, 1),
(6036948, 887051, 2553, '<td valign="top">Beautiful image, the very interesting walkway gives it just the "kick" that sets it apart.</td>', 'Beautiful image, the very interesting walkway gives it just the "kick" that sets it apart.', '2010-06-02 04:45:49.000000', NULL, 1),
(6036950, 886946, 2553, '<td valign="top">Beautifully calming, the color is lovely.</td>', 'Beautifully calming, the color is lovely.', '2010-06-02 04:46:54.000000', NULL, 1),
(6036974, 886582, 2553, '<td valign="top">Now that I am back to comment, I really have to sit and look at this.  The contradictions of stillness and motion, of dark and brilliant color really create so much interest in the image.  I love the little "stars" of lights.  This is an image that I could look at over and over again.  My only "nitpick" would be the tree on the left, but no big deal, it is what it is.</td>', 'Now that I am back to comment, I really have to sit and look at this.  The contradictions of stillness and motion, of dark and brilliant color really create so much interest in the image.  I love the little "stars" of lights.  This is an image that I could look at over and over again.  My only "nitpick" would be the tree on the left, but no big deal, it is what it is.', '2010-06-02 04:54:08.000000', NULL, 1),
(6037571, 886954, 113419, '<td valign="top">I like the bright colors.  Dandelion Festival huh?  I would like to go....in the spring I make dandelion jelly.  I tried to make dandelion wine once but it turned out "gluppy"  lol</td>', 'I like the bright colors.  Dandelion Festival huh?  I would like to go....in the spring I make dandelion jelly.  I tried to make dandelion wine once but it turned out "gluppy"  lol', '2010-06-02 13:14:05.000000', NULL, 1),
(6037573, 886993, 113419, '<td valign="top">this is a marvelous image....if not somewhat sad</td>', 'this is a marvelous image....if not somewhat sad', '2010-06-02 13:14:37.000000', NULL, 1),
(6037575, 886819, 113419, '<td valign="top">I think this would have been a much better image had it not been for the head there in the corner.</td>', 'I think this would have been a much better image had it not been for the head there in the corner.', '2010-06-02 13:15:18.000000', NULL, 1),
(6037576, 886861, 113419, '<td valign="top">nice</td>', 'nice', '2010-06-02 13:15:32.000000', NULL, 1),
(6037583, 887069, 113419, '<td valign="top">I think I would have cropped out the front of that last bus....I say that cause I can find nothing else to pick on.  This is a nice image despite the hard life that is portrayed.</td>', 'I think I would have cropped out the front of that last bus....I say that cause I can find nothing else to pick on.  This is a nice image despite the hard life that is portrayed.', '2010-06-02 13:18:00.000000', NULL, 1),
(6037585, 887055, 113419, '<td valign="top">yes, for now this is beautiful.  a lovely capture of the color blue, your composition is nice and the leading line if perfect.</td>', 'yes, for now this is beautiful.  a lovely capture of the color blue, your composition is nice and the leading line if perfect.', '2010-06-02 13:19:04.000000', NULL, 1),
(6037592, 886719, 113419, '<td valign="top">I had thought of doing a photo of our farmers market; however we don''t have a lovely creek running through ours.  What a lovely place for a market!</td>', 'I had thought of doing a photo of our farmers market; however we don''t have a lovely creek running through ours.  What a lovely place for a market!', '2010-06-02 13:19:49.000000', NULL, 1),
