(6039394, 886987, 27686, '<td valign="top">This is so beautiful!</td>', 'This is so beautiful!', '2010-06-03 15:31:01.000000', NULL, 1),
(6039398, 886696, 27686, '<td valign="top">Great shot!</td>', 'Great shot!', '2010-06-03 15:33:02.000000', NULL, 1),
(6039399, 886956, 27686, '<td valign="top">Wonderful action!</td>', 'Wonderful action!', '2010-06-03 15:34:06.000000', NULL, 1),
(6039400, 886193, 27686, '<td valign="top">Love the crop!</td>', 'Love the crop!', '2010-06-03 15:34:36.000000', NULL, 1),
(6039401, 886920, 27686, '<td valign="top">Great shot.</td>', 'Great shot.', '2010-06-03 15:36:54.000000', NULL, 1),
(6039403, 886231, 27686, '<td valign="top">Lovely setting!</td>', 'Lovely setting!', '2010-06-03 15:38:36.000000', NULL, 1),
(6039405, 887018, 27686, '<td valign="top">Great pic!</td>', 'Great pic!', '2010-06-03 15:41:26.000000', NULL, 1),
(6039406, 886887, 27686, '<td valign="top">Lovely pic and contrast!</td>', 'Lovely pic and contrast!', '2010-06-03 15:42:00.000000', NULL, 1),
(6039407, 886959, 3102, '<td valign="top">I was just there a month ago, and I took some shots from almost this same vantage point.  Now I''m going to spend some time being bummed that the trip is over :)</td>', 'I was just there a month ago, and I took some shots from almost this same vantage point.  Now I''m going to spend some time being bummed that the trip is over :)', '2010-06-03 15:42:11.000000', NULL, 1),
(6039459, 886573, 116241, '<td valign="top">I would have liked this better if it were straight.</td>', 'I would have liked this better if it were straight.', '2010-06-03 16:26:54.000000', NULL, 1),
(6039545, 886565, 110438, '<td valign="top">Very unique work!</td>', 'Very unique work!', '2010-06-03 17:29:42.000000', NULL, 1),
(6039614, 886917, 109227, '<td valign="top">I automatically smiled back at this fella.  Nice capture.</td>', 'I automatically smiled back at this fella.  Nice capture.', '2010-06-03 18:02:18.000000', NULL, 1),
(6039616, 886753, 109227, '<td valign="top">Great capture.</td>', 'Great capture.', '2010-06-03 18:02:53.000000', NULL, 1),
(6039620, 886850, 109227, '<td valign="top">If this HDR (I can only guess), then I like how you did not overdo it like a lot that I see on DPC.  Great shot. 10</td>', 'If this HDR (I can only guess), then I like how you did not overdo it like a lot that I see on DPC.  Great shot. 10', '2010-06-03 18:05:35.000000', NULL, 1),
(6039621, 886986, 109227, '<td valign="top">It is nice to see subtle colors for a change.  Nice capture. 10</td>', 'It is nice to see subtle colors for a change.  Nice capture. 10', '2010-06-03 18:06:02.000000', NULL, 1),
(6039623, 886920, 109227, '<td valign="top">I like the subtle coloring here.  9</td>', 'I like the subtle coloring here.  9', '2010-06-03 18:06:47.000000', NULL, 1),
(6040286, 886786, 93565, '<td valign="top">I really like this- the toning works quite well for this. The perspective really brings home the manner in which the buildings loom over the child.</td>', 'I really like this- the toning works quite well for this. The perspective really brings home the manner in which the buildings loom over the child.', '2010-06-04 06:58:55.000000', NULL, 1),
(6040288, 886983, 93565, '<td valign="top">Things seem too tight, constricted. I want to see what else is around him, what his booth looks like, the bustle or lack of bustling people...more context strengthens these kind of shots.</td>', 'Things seem too tight, constricted. I want to see what else is around him, what his booth looks like, the bustle or lack of bustling people...more context strengthens these kind of shots.', '2010-06-04 07:01:20.000000', NULL, 1),
(6040292, 886850, 93565, '<td valign="top">Subways are something that tons of people see all the time, and thus they are generally thought of as horribly mundane and boring. You''ve taken us beyond that, and reminded us there is interest in the commonplace. Good job.</td>', 'Subways are something that tons of people see all the time, and thus they are generally thought of as horribly mundane and boring. You''ve taken us beyond that, and reminded us there is interest in the commonplace. Good job.', '2010-06-04 07:07:55.000000', NULL, 1),
(6040296, 886899, 93565, '<td valign="top">Great shot. I really like the sense of movement and life that we''re given by the color of the stands and the arms of the fans.</td>', 'Great shot. I really like the sense of movement and life that we''re given by the color of the stands and the arms of the fans.', '2010-06-04 07:12:41.000000', NULL, 1),
(6040419, 886978, 80908, '<td valign="top">Pleasant shot, but a strange red cast (like an old kodak?) detracts slightly.</td>', 'Pleasant shot, but a strange red cast (like an old kodak?) detracts slightly.', '2010-06-04 09:27:18.000000', NULL, 1),
(6040420, 887021, 80908, '<td valign="top">Vibrant, colourful and fun. Immediately appealing.</td>', 'Vibrant, colourful and fun. Immediately appealing.', '2010-06-04 09:27:45.000000', NULL, 1),
(6040422, 886721, 80908, '<td valign="top">Great shot, perfectly exposed. In an FS I would probably have rated this more highly, but it just doesn''t scream ''city life'' to me and I have to be fair to the other entries!</td>', 'Great shot, perfectly exposed. In an FS I would probably have rated this more highly, but it just doesn''t scream ''city life'' to me and I have to be fair to the other entries!', '2010-06-04 09:28:50.000000', NULL, 1),
(6040423, 886673, 80908, '<td valign="top">Simple, nicely explosed, classic.</td>', 'Simple, nicely explosed, classic.', '2010-06-04 09:29:31.000000', NULL, 1),
(6040425, 886986, 80908, '<td valign="top">Almost cartoony tonemapping, but that seems to work here. Very ''city life'' - great job.</td>', 'Almost cartoony tonemapping, but that seems to work here. Very ''city life'' - great job.', '2010-06-04 09:30:11.000000', NULL, 1),
(6040427, 886700, 80908, '<td valign="top">Great angle, but too many bits of the shot seem blown out and distracting for me to really enjoy it.</td>', 'Great angle, but too many bits of the shot seem blown out and distracting for me to really enjoy it.', '2010-06-04 09:31:02.000000', NULL, 1),
(6040429, 886799, 80908, '<td valign="top">Nice technicals and composition - the ''model'' confuses me though. Coming? Going? Who are they?! :o)</td>', 'Nice technicals and composition - the ''model'' confuses me though. Coming? Going? Who are they?! :o)', '2010-06-04 09:32:05.000000', NULL, 1),
(6040433, 886946, 80908, '<td valign="top">Very dual (rather than duo) tone. I don''t find it too appealing - sorry, very blocky with the shadow and light.</td>', 'Very dual (rather than duo) tone. I don''t find it too appealing - sorry, very blocky with the shadow and light.', '2010-06-04 09:33:22.000000', NULL, 1),
(6040434, 886588, 80908, '<td valign="top">Great composition with perfect exposure, but really on the edge for meeting the challenge. I''m sure (actually I know!) that Poole has more ''life'' to offer than this.</td>', 'Great composition with perfect exposure, but really on the edge for meeting the challenge. I''m sure (actually I know!) that Poole has more ''life'' to offer than this.', '2010-06-04 09:34:14.000000', NULL, 1),
(6040435, 886956, 80908, '<td valign="top">Nice action shot - the right choice to go BW I think.</td>', 'Nice action shot - the right choice to go BW I think.', '2010-06-04 09:34:45.000000', NULL, 1),
(6040436, 887081, 80908, '<td valign="top">Very peaceful shot - I am not sure it benefits from the tonemapping though. Wierd artefacts in the sky.</td>', 'Very peaceful shot - I am not sure it benefits from the tonemapping though. Wierd artefacts in the sky.', '2010-06-04 09:35:34.000000', NULL, 1),
(6040437, 886745, 80908, '<td valign="top">Great idea - serious perspective and a slight ''B-movie'' feel to the processing. I can''t imagine that DPC voters will really feel the love, but I think it is great.</td>', 'Great idea - serious perspective and a slight ''B-movie'' feel to the processing. I can''t imagine that DPC voters will really feel the love, but I think it is great.', '2010-06-04 09:36:19.000000', NULL, 1),
(6040438, 887023, 80908, '<td valign="top">Lots of fun - colour and dynamism, isn''t that what sity life is supposed to be all about?</td>', 'Lots of fun - colour and dynamism, isn''t that what sity life is supposed to be all about?', '2010-06-04 09:36:57.000000', NULL, 1),
(6040439, 886889, 80908, '<td valign="top">Really clean nice shot, I like the BW but it is just a little too dark on your subjects for perfection.</td>', 'Really clean nice shot, I like the BW but it is just a little too dark on your subjects for perfection.', '2010-06-04 09:37:40.000000', NULL, 1),
(6040441, 887057, 80908, '<td valign="top">Nice composition, use of the available light and timing. The tourist board should buy this!</td>', 'Nice composition, use of the available light and timing. The tourist board should buy this!', '2010-06-04 09:38:29.000000', NULL, 1),
(6040442, 886850, 80908, '<td valign="top">Virtually perfect composition, slightly psychedelic processing! Hmmm.</td>', 'Virtually perfect composition, slightly psychedelic processing! Hmmm.', '2010-06-04 09:39:11.000000', NULL, 1),
(6040443, 887050, 80908, '<td valign="top">Nice shot and BW conversion. Not very lively.</td>', 'Nice shot and BW conversion. Not very lively.', '2010-06-04 09:39:55.000000', NULL, 1),
(6040444, 886881, 80908, '<td valign="top">Rats! Your challenge is a week out. Great ''church'' shot - in fact quite a nice shot although the angled road is slightly offputting. City life? Hmmm.</td>', 'Rats! Your challenge is a week out. Great ''church'' shot - in fact quite a nice shot although the angled road is slightly offputting. City life? Hmmm.', '2010-06-04 09:40:51.000000', NULL, 1),
(6040445, 886581, 80908, '<td valign="top">A local issue? Slightly dark.</td>', 'A local issue? Slightly dark.', '2010-06-04 09:41:12.000000', NULL, 1),
(6040447, 887079, 80908, '<td valign="top">Fun, but risky to your camera! Perhaps a little brighter on the subject? I suspect the camera is metering evaluatively so that bright sunshine is just killing your little girl.</td>', 'Fun, but risky to your camera! Perhaps a little brighter on the subject? I suspect the camera is metering evaluatively so that bright sunshine is just killing your little girl.', '2010-06-04 09:45:52.000000', NULL, 1),
(6040448, 887055, 80908, '<td valign="top">Pleasant photo, but doesn''t really tell the story for me.</td>', 'Pleasant photo, but doesn''t really tell the story for me.', '2010-06-04 09:46:19.000000', NULL, 1),
(6040449, 886902, 80908, '<td valign="top">Tough one. This is very beautiful - you need to get back there this week! But for ''life in your city''? Seems like a bit of a shoehorn.</td>', 'Tough one. This is very beautiful - you need to get back there this week! But for ''life in your city''? Seems like a bit of a shoehorn.', '2010-06-04 09:47:07.000000', NULL, 1),
(6040450, 886672, 80908, '<td valign="top">Really nicely timed capture, perfectly composed. Front page material perhaps?</td>', 'Really nicely timed capture, perfectly composed. Front page material perhaps?', '2010-06-04 09:47:48.000000', NULL, 1),
(6040451, 886464, 80908, '<td valign="top">When I think about a photo telling a story, this is what I mean! Great job.</td>', 'When I think about a photo telling a story, this is what I mean! Great job.', '2010-06-04 09:48:20.000000', NULL, 1),
(6040452, 887060, 80908, '<td valign="top">Nicely exposed, but not sure about the composition, or what I am supposed to be looking at here.</td>', 'Nicely exposed, but not sure about the composition, or what I am supposed to be looking at here.', '2010-06-04 09:48:56.000000', NULL, 1),
(6040453, 886966, 80908, '<td valign="top">Great idea, really nice exposure and treatment but so little of the ''river'' itself?</td>', 'Great idea, really nice exposure and treatment but so little of the ''river'' itself?', '2010-06-04 09:49:30.000000', NULL, 1),
(6040455, 887072, 80908, '<td valign="top">What? The Bordello? Those dirty sailors... ;o) Nice use of grain.</td>', 'What? The Bordello? Those dirty sailors... ;o) Nice use of grain.', '2010-06-04 09:50:08.000000', NULL, 1),
(6040456, 886553, 80908, '<td valign="top">I like the idea, but the odd angles and the dark subject bring it down a little for me.</td>', 'I like the idea, but the odd angles and the dark subject bring it down a little for me.', '2010-06-04 09:50:47.000000', NULL, 1),
(6040458, 886899, 80908, '<td valign="top">Very topical! Nice clear, well lit stadium shot - I could almost be there.</td>', 'Very topical! Nice clear, well lit stadium shot - I could almost be there.', '2010-06-04 09:51:20.000000', NULL, 1),
(6040459, 886689, 80908, '<td valign="top">Nice moment, captured well.</td>', 'Nice moment, captured well.', '2010-06-04 09:51:44.000000', NULL, 1),
(6040460, 886500, 80908, '<td valign="top">Really nice composition, colours and lighting. I am confused by the heavy tonemapping.</td>', 'Really nice composition, colours and lighting. I am confused by the heavy tonemapping.', '2010-06-04 09:52:29.000000', NULL, 1),
(6040462, 887058, 80908, '<td valign="top">This would have been genius with just a few more people. As it is, I still like it.</td>', 'This would have been genius with just a few more people. As it is, I still like it.', '2010-06-04 09:53:00.000000', NULL, 1),
(6040464, 886898, 80908, '<td valign="top">Hmmm. City life? Could use a little more contrast - seems a little flat.</td>', 'Hmmm. City life? Could use a little more contrast - seems a little flat.', '2010-06-04 09:53:30.000000', NULL, 1),
(6040466, 886193, 80908, '<td valign="top">Slightly dark, not convinced by the composition, but a nice peaceful feel to this.</td>', 'Slightly dark, not convinced by the composition, but a nice peaceful feel to this.', '2010-06-04 09:54:03.000000', NULL, 1),
(6040467, 886953, 80908, '<td valign="top">Great treatment, nicely composed shot.</td>', 'Great treatment, nicely composed shot.', '2010-06-04 09:54:25.000000', NULL, 1),
(6040468, 886829, 80908, '<td valign="top">Now here''s a real moment of city life!</td>', 'Now here''s a real moment of city life!', '2010-06-04 09:54:45.000000', NULL, 1),
(6040469, 887078, 80908, '<td valign="top">Interesting, but seems rather overexposed strangely. Not sure what I am looking at here? What is the story?</td>', 'Interesting, but seems rather overexposed strangely. Not sure what I am looking at here? What is the story?', '2010-06-04 09:55:27.000000', NULL, 1),
(6040470, 886813, 80908, '<td valign="top">Pretty, but the high contrasts do leave it looking somewhat ''blocky''.</td>', 'Pretty, but the high contrasts do leave it looking somewhat ''blocky''.', '2010-06-04 09:56:01.000000', NULL, 1),
(6040471, 887054, 80908, '<td valign="top">Yes, it is. Perfect exposure, lively subject.</td>', 'Yes, it is. Perfect exposure, lively subject.', '2010-06-04 09:56:34.000000', NULL, 1),
(6040472, 886861, 80908, '<td valign="top">nice clean composition. Strong technicals and a very fine subject!</td>', 'nice clean composition. Strong technicals and a very fine subject!', '2010-06-04 09:57:45.000000', NULL, 1),
(6040474, 886791, 80908, '<td valign="top">This is just lovely. Great job on all fronts.</td>', 'This is just lovely. Great job on all fronts.', '2010-06-04 09:58:30.000000', NULL, 1),
(6040475, 886489, 80908, '<td valign="top">Nice moment, well captured.</td>', 'Nice moment, well captured.', '2010-06-04 09:59:15.000000', NULL, 1),
(6040478, 886945, 80908, '<td valign="top">Lovely subject and composition, but I am not sure that this is as clear as it needs to be.</td>', 'Lovely subject and composition, but I am not sure that this is as clear as it needs to be.', '2010-06-04 10:01:01.000000', NULL, 1),
(6040481, 886572, 80908, '<td valign="top">Nice dynamic shot. Seems rather noisy, which is odd in bright daylight.</td>', 'Nice dynamic shot. Seems rather noisy, which is odd in bright daylight.', '2010-06-04 10:02:46.000000', NULL, 1),
(6040483, 887069, 80908, '<td valign="top">nice capture. plenty of story here!</td>', 'nice capture. plenty of story here!', '2010-06-04 10:04:07.000000', NULL, 1),
(6040484, 886965, 80908, '<td valign="top">Everything works here, except that it seems rather dark.</td>', 'Everything works here, except that it seems rather dark.', '2010-06-04 10:04:45.000000', NULL, 1),
(6040485, 886993, 80908, '<td valign="top">Great moment of city life. Excellent work in all respects.</td>', 'Great moment of city life. Excellent work in all respects.', '2010-06-04 10:05:12.000000', NULL, 1),
(6040486, 886573, 80908, '<td valign="top">Rather dark, and I don''t see what the angle adds?</td>', 'Rather dark, and I don''t see what the angle adds?', '2010-06-04 10:05:35.000000', NULL, 1),
(6040487, 886960, 80908, '<td valign="top">Nice composition. Slightly overexposed it seems, but for me this highlights the ''burning sun'' of midday and is a positive.</td>', 'Nice composition. Slightly overexposed it seems, but for me this highlights the ''burning sun'' of midday and is a positive.', '2010-06-04 10:06:59.000000', NULL, 1),
(6040817, 886953, 57447, '<td valign="top">I really like the tones you used.</td>', 'I really like the tones you used.', '2010-06-04 14:42:41.000000', NULL, 1),
(6040818, 886962, 57447, '<td valign="top">Invigorating surprise.</td>', 'Invigorating surprise.', '2010-06-04 14:43:31.000000', NULL, 1),
(6040819, 887023, 57447, '<td valign="top">Could not or would not?</td>', 'Could not or would not?', '2010-06-04 14:44:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6041242, 887050, 58031, '<td valign="top">I like how the sky looks forboding. It''s nice how the lines draw your eyes to the top of the lighthouse peak.</td>', 'I like how the sky looks forboding. It''s nice how the lines draw your eyes to the top of the lighthouse peak.', '2010-06-04 20:33:33.000000', NULL, 1),
(6041358, 886983, 50864, '<td valign="top">One of my favorites. 10</td>', 'One of my favorites. 10', '2010-06-04 22:53:53.000000', NULL, 1),
(6041362, 887031, 50864, '<td valign="top">Really gives a feel for the activity.  One of my favorites. 10</td>', 'Really gives a feel for the activity.  One of my favorites. 10', '2010-06-04 22:55:19.000000', NULL, 1),
(6041363, 886677, 50864, '<td valign="top">Perfect capture. 10</td>', 'Perfect capture. 10', '2010-06-04 22:55:42.000000', NULL, 1),
(6041364, 886231, 50864, '<td valign="top">Love this. 9</td>', 'Love this. 9', '2010-06-04 22:56:03.000000', NULL, 1),
(6041366, 886817, 50864, '<td valign="top">Beautifully captured. 9</td>', 'Beautifully captured. 9', '2010-06-04 22:56:26.000000', NULL, 1),
(6041367, 886753, 50864, '<td valign="top">Eileen just makes this shot.  I love it. 9</td>', 'Eileen just makes this shot.  I love it. 9', '2010-06-04 22:56:55.000000', NULL, 1),
(6041369, 886637, 50864, '<td valign="top">Wonderfully shot.  I feel like I''m in the park.</td>', 'Wonderfully shot.  I feel like I''m in the park.', '2010-06-04 22:57:43.000000', NULL, 1),
(6041373, 886979, 50864, '<td valign="top">Great shot and perfect title.</td>', 'Great shot and perfect title.', '2010-06-04 22:58:48.000000', NULL, 1),
(6041761, 886721, 23317, '<td valign="top">Spectacular colors at the night glow.</td>', 'Spectacular colors at the night glow.', '2010-06-05 10:01:30.000000', NULL, 1),
(6041819, 886931, 101394, '<td valign="top">beautiful!</td>', 'beautiful!', '2010-06-05 11:13:39.000000', NULL, 1),
(6041882, 886553, 76335, '<td valign="top">That''s a pretty fascinating composition.</td>', 'That''s a pretty fascinating composition.', '2010-06-05 13:30:24.000000', NULL, 1),
(6041884, 886700, 76335, '<td valign="top">Nice idea. Is this HDR? The exposure feels a little artificial. People are kind of distracting -- either need to be closer and more connected to the subject or further back and relegated to the background.</td>', 'Nice idea. Is this HDR? The exposure feels a little artificial. People are kind of distracting -- either need to be closer and more connected to the subject or further back and relegated to the background.', '2010-06-05 13:32:10.000000', NULL, 1),
(6041886, 886861, 76335, '<td valign="top">Nicely balanced and humorous composition. New England?</td>', 'Nicely balanced and humorous composition. New England?', '2010-06-05 13:33:02.000000', NULL, 1),
(6041887, 886565, 76335, '<td valign="top">Great idea. Beautifully done.</td>', 'Great idea. Beautifully done.', '2010-06-05 13:33:31.000000', NULL, 1),
(6041889, 886673, 76335, '<td valign="top">Nice forms and shadows in this. I like the subtle colors of evening throughout.</td>', 'Nice forms and shadows in this. I like the subtle colors of evening throughout.', '2010-06-05 13:34:18.000000', NULL, 1),
(6041891, 886737, 76335, '<td valign="top">Nice scene. Needs a little something more maybe -- blurred pedestrians, light streaks from a car...</td>', 'Nice scene. Needs a little something more maybe -- blurred pedestrians, light streaks from a car...', '2010-06-05 13:35:10.000000', NULL, 1),
(6041893, 886920, 76335, '<td valign="top">A good busy scene and full of life. Feels overprocessed to my eyes.</td>', 'A good busy scene and full of life. Feels overprocessed to my eyes.', '2010-06-05 13:35:54.000000', NULL, 1),
(6041894, 887055, 76335, '<td valign="top">Heartbreaking, isn''t it?</td>', 'Heartbreaking, isn''t it?', '2010-06-05 13:36:16.000000', NULL, 1),
(6041897, 886887, 76335, '<td valign="top">Wonderful -- very Sunday morning. Looks great in black and white. Do kids still read the funnies? Looks like the boy''s found his bliss in the sports section.</td>', 'Wonderful -- very Sunday morning. Looks great in black and white. Do kids still read the funnies? Looks like the boy''s found his bliss in the sports section.', '2010-06-05 13:37:29.000000', NULL, 1),
(6042003, 886538, 76335, '<td valign="top">Shows life indirectly, I guess. Nitpicky challenge criteria aside, this is an outstanding photograph.</td>', 'Shows life indirectly, I guess. Nitpicky challenge criteria aside, this is an outstanding photograph.', '2010-06-05 15:21:10.000000', NULL, 1),
(6042005, 887069, 76335, '<td valign="top">This is an excellent photograph. I wish you had gotten closer though. The telephoto kind of flattens everything to no good effect.</td>', 'This is an excellent photograph. I wish you had gotten closer though. The telephoto kind of flattens everything to no good effect.', '2010-06-05 15:22:36.000000', NULL, 1),
(6042009, 886962, 76335, '<td valign="top">Looks like a front pager to me. Has an ominous feel to it. Nice.</td>', 'Looks like a front pager to me. Has an ominous feel to it. Nice.', '2010-06-05 15:23:18.000000', NULL, 1),
(6042010, 886978, 76335, '<td valign="top">Nice scene. The colors are bit garish -- too much on the blue/purple side.</td>', 'Nice scene. The colors are bit garish -- too much on the blue/purple side.', '2010-06-05 15:23:54.000000', NULL, 1),
(6042011, 887030, 76335, '<td valign="top">Intense. Nicely done.</td>', 'Intense. Nicely done.', '2010-06-05 15:24:29.000000', NULL, 1),
(6042066, 887022, 76335, '<td valign="top">The man''s in heaven. Great slice of life.</td>', 'The man''s in heaven. Great slice of life.', '2010-06-05 16:37:21.000000', NULL, 1),
(6042067, 886786, 76335, '<td valign="top">Effectively framed for maximun effect. I do like the sepia processing also.</td>', 'Effectively framed for maximun effect. I do like the sepia processing also.', '2010-06-05 16:37:44.000000', NULL, 1),
(6042071, 886882, 76335, '<td valign="top">Great scene, beautifully processed in black and white. The contrast is most effective.</td>', 'Great scene, beautifully processed in black and white. The contrast is most effective.', '2010-06-05 16:39:14.000000', NULL, 1),
(6042072, 886681, 76335, '<td valign="top">More about your living room than your city. A nice still life anyway.</td>', 'More about your living room than your city. A nice still life anyway.', '2010-06-05 16:39:55.000000', NULL, 1),
(6042073, 886489, 76335, '<td valign="top">They''re having fun. Nice poses.</td>', 'They''re having fun. Nice poses.', '2010-06-05 16:40:14.000000', NULL, 1),
